public TreeNode<T> rotateRight(TreeNode<T> node) {
TreeNode<T> parent = node.getParent();
if (parent == null) {
throw new IllegalArgumentException("Cannot perform rotation on root node");
}
TreeNode<T> grandparent = parent.getParent();
if (grandparent == null) {
throw new IllegalArgumentException("Cannot perform rotation on node with no grandparent");
}

grandparent.replaceChild(parent, node);
parent.replaceChild(node, node.getRightChild());
node.setRightChild(parent);

return parent;
}

public TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> temp = node.left;
    node.left = temp.right;
    temp.right = node;
    return temp;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> parent = node.getParent();
    TreeNode<T> child = node.getSmallestChild();
    child.setParent(parent);
    parent.setSmallestChild(child);
    node.setParent(child);
    child.setSmallestChild(node);
    return child;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        throw new IllegalArgumentException("node cannot be null");
    }
    if (node.right == null) {
        return node;
    }
    TreeNode<T> nodeLeft = node.left;
    TreeNode<T> nodeRight = node.right;
    node.left = nodeRight.right;
    node.right = nodeRight.left;
    nodeRight.left = node;
    nodeRight.right = nodeLeft;
    return nodeRight;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    TreeNode<T> newParent = node.left;
    node.left = newParent.right;
    newParent.right = node;
    return newParent;
}

