public class AddToClassPath {

    @SuppressWarnings("unchecked")
    public static void addToClassPath(Vector<URL> cpV, String dir) {
        try {
            // Get the path for the given directory
            Path p = Paths.get(dir);

            // Check if the path is a directory
            if (Files.isDirectory(p)) {
                // Get the list of files in the directory
                List<Path> files = Files.list(p).collect(Collectors.toList());

                // Filter the list to only include .jar files
                List<Path> jarFiles = files.stream().filter(f -> f.toString().endsWith(".jar")).collect(Collectors.toList());

                // Add the .jar files to the classpath vector
                for (Path jarFile : jarFiles) {
                    cpV.add(jarFile.toUri().toURL());
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

