    for (int i = 0; i < numArgs; i++) {
        Object arg = arguments[i];
        if (arg instanceof String) {
            String str = (String) arg;
            buf.append(str);
        } else if (arg instanceof Integer) {
            int num = (Integer) arg;
            buf.append(num);
        } else if (arg instanceof Float) {
            float num = (Float) arg;
            buf.append(num);
        } else if (arg instanceof Double) {
            double num = (Double) arg;
            buf.append(num);
        }
    }
    return buf.toString();
}

