    } else {
        file.deleteOnExit();

        // If file is a directory, recursively delete all sub-directories and files.        
        if (file.isDirectory()) {
            File[] subFiles = file.listFiles();
            for (File subFile: subFiles) {
                forceDeleteOnExit(subFile);
            }
        }
    }

