@Override
public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Validate input
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and result map cannot be null");
    }

    // Create a set to store the edges
    Set<E> edges = new HashSet<>();

    // Iterate over the vertices in the result map
    for (Map.Entry<String,V> entry : resultMap.entrySet()) {
        // Get the current vertex
        String vertex = entry.getKey();

        // Iterate over the neighbors of the current vertex
        for (Map.Entry<String,V> neighborEntry : resultMap.entrySet()) {
            // Add an edge between the current vertex and its neighbor
            edges.add(new Edge<>(vertex, neighborEntry.getKey()));
        }
    }

    // Add all the edges to the target graph
    target.addAll(edges);
}

