    // Check if the generic type is actually a parameterized type
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    // Get the actual type arguments for the generic type
    TypeVariable<? extends Class<?>>[] typeParameters = targetType.getTypeParameters();
    Type[] typeArguments = ((ParameterizedType) genericType).getActualTypeArguments();

    // If the number of type arguments does not match the number of type parameters, we cannot resolve the arguments
    if (typeArguments.length != typeParameters.length) {
        return null;
    }

    // Create a map to map type parameters to their corresponding actual type arguments
    Map<TypeVariable<?>, Type> typeParameterMap = new HashMap<>();
    for (int i = 0; i < typeParameters.length; i++) {
        typeParameterMap.put(typeParameters[i], typeArguments[i]);
    }

    // Resolve the actual type arguments for the generic type using the type parameter map
    Class<?>[] resolvedTypes = new Class<?>[typeParameters.length];
    for (int i = 0; i < typeParameters.length; i++) {
        Type typeArgument = typeArguments[i];
        if (typeArgument instanceof Class) {
            resolvedTypes[i] = (Class<?>) typeArgument;
        } else if (typeArgument instanceof ParameterizedType) {
            resolvedTypes[i] = (Class<?>) ((ParameterizedType) typeArgument).getRawType();
        } else if (typeArgument instanceof TypeVariable) {
            Type resolvedType = typeParameterMap.get(typeArgument);
            if (resolvedType instanceof Class) {
                resolvedTypes[i] = (Class<?>) resolvedType;
            } else {
                return null;
            }
        } else {
            return null;
        }
    }

    return resolvedTypes;
}

