private static Class<?> resolveTypeVariable(Class<?> targetType, TypeVariable<?> typeVariable) {
    Class<?> clazz = targetType;
    while (true) {
        if (clazz.getTypeParameters().length > 0) {
            for (int i = 0; i < clazz.getTypeParameters().length; i++) {
                if (clazz.getTypeParameters()[i].equals(typeVariable)) {
                    return clazz.getTypeParameters()[i];
                }
            }
        }
        clazz = clazz.getSuperclass();
        if (clazz == null) {
            return null;
        }
    }
}

