protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = end - start;

    if (duration > FETCH_DATA_DURATION) {
        long numSplits = duration / FETCH_DATA_DURATION;
        long splitDuration = duration / numSplits;
        for (int i = 0; i < numSplits; i++) {
            long splitStart = start + (i * splitDuration);
            long splitEnd = splitStart + splitDuration;
            timeRanges.add(new TimeRange(splitStart, splitEnd));
        }
    } else {
        timeRanges.add(new TimeRange(start, end));
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Initialize the time range list
    List<TimeRange> timeRanges = new ArrayList<>();

    // Calculate the difference between the start and end times
    long diff = Math.abs(start - end);

    // If the difference is greater than FETCH_DATA_DURATION, split the time range
    if (diff > FETCH_DATA_DURATION) {
        // Calculate the number of time ranges required
        int numRanges = (int) Math.floor(diff / FETCH_DATA_DURATION);

        // Create the time ranges
        for (int i = 0; i < numRanges; i++) {
            long newStart = start + (i * FETCH_DATA_DURATION);
            long newEnd = newStart + FETCH_DATA_DURATION;
            timeRanges.add(new TimeRange(newStart, newEnd));
        }
    } else {
        // If the difference is less than or equal to FETCH_DATA_DURATION, add a single time range
        timeRanges.add(new TimeRange(start, end));
    }

    return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    while (start < end) {
        long duration = Math.min(end - start, FETCH_DATA_DURATION);
        timeRanges.add(new TimeRange(start, duration));
        start += duration;
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> result = new ArrayList<>();
    long duration = end - start;
    long fetchInterval = FETCH_DATA_DURATION / FETCH_DATA_COUNT;
    long count = duration / fetchInterval;
    long remainder = duration % fetchInterval;
    for (long i = 0; i < count; i++) {
        long offset = i * fetchInterval;
        result.add(new TimeRange(start + offset, start + offset + fetchInterval));
    }
    if (remainder != 0) {
        result.add(new TimeRange(start + duration - remainder, end));
    }
    return result;
}

