            while (currentLength < newLength) {
                currentLength = (int) Math.min(currentLength * 2L, Integer.MAX_VALUE);
            }
            data = Arrays.copyOf(data, currentLength);
        }
        for (int i = byteOffset; i < byteOffset + byteLength; i++) {
            data[i] = 0;
        }
        length = newLength;
        return this;
