        }
        int currentLength = length;
        while (currentLength < (byteOffset + byteLength)) {
            currentLength = (int) Math.min(currentLength * 2L, Integer.MAX_VALUE);
        }
        data = Arrays.copyOf(data, currentLength);
        System.arraycopy(byteArrayValue, byteOffset, data, byteOffset, byteLength);
