void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor cannot be null");
    }
    if (descriptor.isEmpty()) {
        return;
    }
    Type[] types = Signature.getParameterTypes(descriptor);
    if (types.length == 0) {
        return;
    }
    Stack<Type> stack = new Stack<>();
    for (Type type : types) {
        if (type.getSort() != Type.METHOD) {
            stack.push(type);
        }
    }
    while (!stack.empty()) {
        pop(stack.pop());
    }
}

