private void pop(final String descriptor) {
    List<Integer> poppedTypes = new ArrayList<>();
    String[] split = descriptor.split("\\s+");
    for (String token : split) {
        if (token.equals("")) {
            continue;
        }
        if (token.equals("[")) {
            poppedTypes.add(Integer.MAX_VALUE);
        } else if (token.equals("L")) {
            poppedTypes.add(Integer.MIN_VALUE);
        } else if (token.equals(";")) {
            break;
        } else {
            poppedTypes.add(Integer.parseInt(token));
        }
    }
    while (!poppedTypes.isEmpty()) {
        int type = poppedTypes.remove(poppedTypes.size() - 1);
        if (type == Integer.MAX_VALUE) {
            // Pop an array
            Output<Object[]> array = popFrame();
            // Pop all elements of the array
            while (array.hasMore()) {
                Output<Object> element = popFrame();
                array.take(element.read(type));
            }
        } else if (type == Integer.MIN_VALUE) {
            // Pop a list
            Output<List<Object>> list = popFrame();
            // Pop all elements of the list
            while (list.hasMore()) {
                Output<Object> element = popFrame();
                list.take(element.read(type));
            }
        } else {
            // Pop a single value
            Output<?> value = popFrame();
            value.read(type);
        }
    }
}

void pop(String descriptor) {
    if (descriptor.startsWith(")")) {
        int numArguments = descriptor.substring(1, descriptor.length() - 1).length();
        for (int i = 0; i < numArguments; i++) {
            outputFrameStack.pop();
        }
    } else {
        outputFrameStack.pop();
    }
}

private void pop(final String descriptor){
    int numTypes = descriptor.endsWith(")") ? descriptor.length() - 1 : descriptor.length();
    for (int i = 0; i < numTypes; i++) {
        Type type = Type.getType(descriptor.substring(i, i + 1));
        if (!outputFrames.pop().getType().equals(type)) {
            throw new IllegalArgumentException("Type mismatch: expected " + type + ", got " + outputFrames.get(i).getType());
        }
    }
}

