public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    float xCenter = box.getXCenter();
    float width = box.getWidth();
    float halfWidth = width / 2;
    Box2D box1 = new Box2D(xCenter - halfWidth, box.getYCenter(), halfWidth, box.getHeight());
    Box2D box2 = new Box2D(xCenter, box.getYCenter(), halfWidth, box.getHeight());
    return new Pair<>(box1, box2);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double x = box.getMinX();
    double y = box.getMinY();
    double width = box.getWidth();
    double height = box.getHeight();

    double midX = x + width / 2;

    Box2D box1 = new Box2D(x, y, midX, y + height);
    Box2D box2 = new Box2D(midX, y, x + width, y + height);

    return new Pair<>(box1, box2);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double minX = box.minX();
    double maxX = box.maxX();
    double midX = (minX + maxX) / 2;
    Box2D box1 = new Box2D(minX, box.minY(), midX, box.maxY());
    Box2D box2 = new Box2D(midX, box.minY(), maxX, box.maxY());
    return new Pair<>(box1, box2);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    Point2D center = box.getCenter();
    double splitX = center.getX();
    Box2D leftBox = new Box2D(center, new Point2D(splitX, box.getMaxY()));
    Box2D rightBox = new Box2D(new Point2D(splitX, box.getMinY()), center);
    return Pair.of(leftBox, rightBox);
}

