private void putAbstractTypes(final int start, final int end) throws IOException {
    List<Object> abstractTypes = new ArrayList<>();

    // Iterate over the types in the current frame
    for (int i = start; i < end; i++) {
        Object type = currentFrame.get(i);

        // Convert the type to the JVMS verification_type_info format
        String jvmType = "";
        if (type instanceof Integer) {
            jvmType = "I";
        } else if (type instanceof Float) {
            jvmType = "F";
        } else if (type instanceof Double) {
            jvmType = "D";
        } else if (type instanceof Long) {
            jvmType = "J";
        } else if (type instanceof Class) {
            jvmType = "L" + ((Class) type).getName().replace('.', '/') + ";";
        } else if (type instanceof Array) {
            jvmType = "[" + putAbstractTypes(0, ((Array) type).getLength());
        } else if (type instanceof MethodType) {
            jvmType = "(" + putAbstractTypes(0, ((MethodType) type).getParameterCount());
        } else {
            throw new IllegalArgumentException("Unsupported type: " + type);
        }

        abstractTypes.add(jvmType);
    }

    // Write the types to the stack map table entries
    for (int i = 0; i < abstractTypes.size(); i++) {
        stackMapTableEntries.add(abstractTypes.get(i));
    }
}

