void write(byte[] b) throws IOException {
    if (b == null) {
        throw new NullPointerException();
    }
    if (b.length == 0) {
        return;
    }
    ensureOpen();
    int bytesToWrite = b.length;
    while (bytesToWrite > 0) {
        int bytesWritten = Math.min(bytesToWrite, this.buffer.length - this.position);
        System.arraycopy(b, b.length - bytesToWrite, this.buffer, this.position, bytesWritten);
        bytesToWrite -= bytesWritten;
        this.position += bytesWritten;
        if (this.position == this.buffer.length) {
            flushInternal();
        }
    }
}

