    }
    if (b.length == 0) {
        return;
    }
    if (b.length <= this.buf.length - this.count) {
        System.arraycopy(b, 0, this.buf, this.count, b.length);
        this.count += b.length;
    } else {
        flush();
        if (b.length > this.buf.length) {
            this.out.write(b);
        } else {
            System.arraycopy(b, 0, this.buf, 0, b.length);
            this.count = b.length;
        }
    }
}

