public Object convertToType(Class<?> type, Object value) throws Exception {
    if (type == Character.class) {
        if (value instanceof String) {
            String strValue = (String) value;
            if (strValue.length() == 1) {
                return Character.valueOf(strValue.charAt(0));
            } else {
                throw new Exception("Cannot convert string of length " + strValue.length() + " to Character");
            }
        } else {
            throw new Exception("Cannot convert " + value.getClass().getSimpleName() + " to Character");
        }
    }
    throw new Exception("Cannot convert " + value.getClass().getSimpleName() + " to " + type.getSimpleName());
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == Character.class) {
        if (value instanceof String && ((String) value).length() > 1) {
            throw new Exception("Cannot convert a String with more than one character to a Character");
        } else if (value instanceof Character) {
            return value;
        } else if (value instanceof Number) {
            return (char) ((Number) value).intValue();
        } else if (value instanceof Boolean) {
            return (char) (((Boolean) value) ? 1 : 0);
        } else {
            throw new Exception("Cannot convert '" + value.getClass().getName() + "' to Character");
        }
    } else {
        throw new Exception("Cannot convert to type " + type.getName());
    }
}

