public static int nextPrime(int desiredCapacity) {
    // Implementation of the Sieve of Eratosthenes algorithm to find the next prime number
    int prime = Math.max(desiredCapacity + 1, 3);
    boolean[] isPrime = new boolean[prime + 1];
    Arrays.fill(isPrime, true);
    for (int p = 2; p * p <= prime; p++) {
        if (isPrime[p]) {
            for (int i = p * 2; i <= prime; i += p) {
                isPrime[i] = false;
            }
        }
    }
    for (int i = desiredCapacity; i <= prime; i++) {
        if (isPrime[i]) {
            return i;
        }
    }
    return prime;
}

