public final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) throws IOException {
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= constantPool.size()) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }
    ConstantPoolEntry entry = constantPool.get(constantPoolEntryIndex);
    if (entry.getTag() != ConstantPoolEntry.CONSTANT_Utf8) {
        throw new IllegalArgumentException("Invalid constant pool entry type: " + entry.getTag());
    }
    int length = entry.getLength();
    if (charBuffer.length < length) {
        throw new IllegalArgumentException("Char buffer must be at least " + length + " characters long");
    }
    byte[] bytes = entry.getData();
    int pos = 0;
    int i = 0;
    while (pos < length) {
        charBuffer[i++] = (char) (((bytes[pos++] & 0xFF) << 8) + (bytes[pos++] & 0xFF));
    }
    return new String(charBuffer, 0, i);
}

