private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    boolean forward = dir == 1;
    OuterFaceCirculator circ = new OuterFaceCirculator(start, forward);
    while (true) {
        Node node = circ.getNode();
        if (predicate.test(node)) {
            return circ;
        }
        if (node == stop) {
            return null;
        }
        circ.move(forward ? 1 : -1);
    }
}

