    OuterFaceCirculator circulator = new OuterFaceCirculator(start);
    while (circulator.getNextNode() != stop) {
        if (predicate.test(circulator.getCurrentNode())) {
            return circulator;
        }
        circulator.advance(dir);
    }
    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (circulator.getNext() != stop) {
        Node nextNode = circulator.getNext();
        if (predicate.test(nextNode)) {
            return new OuterFaceCirculator(nextNode, dir);
        }
        circulator.setCurrent(nextNode);
    }
    return new OuterFaceCirculator(stop, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (circulator.getNode() != stop) {
        if (predicate.test(circulator.getNode())) {
            break;
        }
        circulator.moveToNext();
    }
    return circulator;
}

