    Node curr = start;
    while (curr != stop) {
        if (predicate.test(curr)) {
            return new OuterFaceCirculator(curr, dir);
        }
        curr = getNextNodeOnOuterFace(curr, dir);
    }
    return new OuterFaceCirculator(stop, dir);
}

