public final MatchResult match(CharSequence uri){
    Map<String, Integer> segmentToRemainingSegments = new HashMap<>();
    for (Pattern segment : patternToRemainingSegments.keySet()) {
        Matcher matcher = segment.matcher(uri);
        if (matcher.find()) {
            Integer remainingSegments = patternToRemainingSegments.get(segment);
            if (remainingSegments == 0) {
                return new MatchResult(matcher);
            } else {
                segmentToRemainingSegments.put(segment, --remainingSegments);
            }
        }
    }
    return null;
}

