}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edges = new ArrayList<E>(tour);
    List<V> vertices = new ArrayList<V>();
    for (E edge : edges) {
        vertices.add(graph.getEdgeSource(edge));
        vertices.add(graph.getEdgeTarget(edge));
    }
    return new GraphWalk<V,E>(graph, vertices, edges);
}

public GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
        if (tour == null || graph == null) {
            throw new IllegalArgumentException("tour and graph cannot be null");
        }
        if (tour.isEmpty()) {
            return new GraphPath<V,E>(graph, Collections.emptyList(), Collections.emptyList());
        }
        List<E> edgeList = new ArrayList<E>(tour);
        List<V> vertexList = new ArrayList<V>();
        vertexList.add(graph.getEdgeSource(edgeList.get(0)));
        for (int i = 0; i < edgeList.size(); i++) {
            E edge = edgeList.get(i);
            vertexList.add(graph.getEdgeTarget(edge));
        }
        return new GraphPath<V,E>(graph, edgeList, vertexList);
    }

