protected void appendDetail(StringBuffer buffer, String fieldName, byte[] array) {
    int bytesInRow = 16;
    buffer.append(String.format("%n  %s = byte[%d] {", fieldName, array.length));
    for (int i = 0; i < array.length; i++) {
        if (i % bytesInRow == 0) {
            buffer.append(String.format("%n    %04d: ", i));
        }
        buffer.append(String.format("0x%02x, ", array[i]));
    }
    buffer.append(String.format("%n  }%n"));
}

protected void appendDetail(StringBuffer buffer, String fieldName, byte[] array) {
    buffer.append(fieldName);
    buffer.append("=");
    if (array == null) {
        buffer.append("null");
    } else {
        buffer.append("byte[").append(array.length).append("]");
        for (int i = 0; i < array.length; i++) {
            buffer.append(" ")
                  .append(Integer.toHexString(array[i] & 0xFF))
                  .append(" ")
                  .append(Character.toString((char) array[i]));

        }
    }
    buffer.append(" ");
}

