public void overrideName(String oldName, String newName) {

    // Check if the new name is already used
    boolean newNameAlreadyExists = false;
    for (ColumnName column : columnNames) {
        if (column.getStorageName().equals(newName)) {
            newNameAlreadyExists = true;
            break;
        }
    }

    // Check if the old name exists
    boolean oldNameFound = false;
    for (ColumnName column : columnNames) {
        if (column.getStorageName().equals(oldName)) {
            oldNameFound = true;
            break;
        }
    }

    // Rename if possible
    if (oldNameFound && !newNameAlreadyExists) {
        for (ColumnName column : columnNames) {
            if (column.getStorageName().equals(oldName)) {
                column.setStorageName(newName);
            }
        }
    }
}

