public static final <V> void reverse(V[] arr, int from, int to) {
    for (int i = from; i < to; i++) {
        int opposite = (to - i) + from - 1;
        V temp = arr[i];
        arr[i] = arr[opposite];
        arr[opposite] = temp;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
	int length = to - from + 1;
	for (int i = 0; i < length / 2; i++) {
		int opposite = length - i - 1;
		V temp = arr[from + i];
		arr[from + i] = arr[to - opposite];
		arr[to - opposite] = temp;
	}
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("arr cannot be null");
    }
    if (from < 0 || from >= arr.length) {
        throw new IllegalArgumentException("from index out of bounds");
    }
    if (to < 0 || to >= arr.length) {
        throw new IllegalArgumentException("to index out of bounds");
    }
    for (int i = from, j = to; i < j; i++, j--) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

