    }
    if (s.isEmpty()) {
        return s;
    }

    // Check for correct format
    if (!s.matches("^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{3}=|[A-Za-z0-9+/]{2}==)?$")) {
