private List<Integer> computeUpperBounds(List<K> keys) {
    // Initialize the upper bounds list with the first key
    List<Integer> upperBounds = Arrays.asList(keys.get(0));

    // Iterate over the remaining keys
    for (int i = 1; i < keys.size(); i++) {
        // Get the current key
        K key = keys.get(i);

        // Find the smallest upper bound that is greater than or equal to the current key
        int upperBound = upperBounds.stream()
                .filter(x -> x >= key)
                .min()
                .orElseThrow();

        // Add the current key to the upper bounds list
        upperBounds.add(upperBound);
    }

    return upperBounds;
}

List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<>();
    for (int i = 0; i < keys.size(); i++) {
        int key = keys.get(i);
        int upperBound = key;
        for (int j = i + 1; j < keys.size(); j++) {
            int otherKey = keys.get(j);
            if (otherKey < key) {
                upperBound = otherKey;
                break;
            }
        }
        upperBounds.add(upperBound);
    }
    return upperBounds;
}

