public static String applyRelativePath(String path, String relativePath) throws Exception {
	if (!relativePath.startsWith("/")) {
		throw new Exception("Relative path must start with a '/'");
	}
	if (path.endsWith("/")) {
		path = path.substring(0, path.length() - 1);
	}
	while (relativePath.endsWith("/")) {
		relativePath = relativePath.substring(0, relativePath.length() - 1);
	}
	String[] folders = relativePath.split("/");
	StringBuilder resultPath = new StringBuilder();
	for (String folder : folders) {
		if (folder.equals("..")) {
			int index = path.lastIndexOf("/", resultPath.length());
			resultPath.deleteCharAt(index);
		} else {
			resultPath.append(folder);
			resultPath.append("/");
		}
	}
	resultPath.deleteCharAt(resultPath.length() - 1);
	return resultPath.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }
    String[] parts = relativePath.split("/");
    for (String part : parts) {
        if (part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            int lastSlash = path.lastIndexOf("/");
            if (lastSlash >= 0) {
                path = path.substring(0, lastSlash);
            }
        } else {
            path += "/" + part;
        }
    }
    return path;
}

