public Edge edgeToNext(){
    if(currentNode == null){
        throw new NoSuchElementException("No current node");
    }
    if(nextNode == null){
        throw new NoSuchElementException("No next node");
    }

    // Check if either current or next node is virtual
    Node realCurrentNode = currentNode.isVirtual() ? currentNode.getRealNode() : currentNode;
    Node realNextNode = nextNode.isVirtual() ? nextNode.getRealNode() : nextNode;

    // Get the edge between the real nodes
    Edge edge = realCurrentNode.getEdge(realNextNode);

    if(edge == null){
        throw new IllegalStateException("No edge between real nodes");
    }

    return edge;
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    boolean doesMatch = false;

    if (str.length() - index >= substring.length()) {
        doesMatch = true;

        for (int i = 0; i < substring.length(); i++) {
            if (str.charAt(index + i) != substring.charAt(i)) {
                doesMatch = false;
                break;
            }
        }
    }

    return doesMatch;
}

