public int readTag() throws IOException {
    // Read a byte into the buffer
    int type = readRawByte();
    if (type == -1) {
        // We've reached EOF
        return 0;
    }

    // Read the remaining 3 bytes
    int tag = readRawByte() << 16;
    tag |= readRawByte() << 8;
    tag |= readRawByte();

    return (type << 28) | tag;
}

