      result = bytes[offset++] & 0xFF;
    }
    return result;
}

public class ByteVector {
    private int[] data;
    private int length;

    public ByteVector() {
        this.data = new int[10];
        this.length = 0;
    }

    public ByteVector put11(final int byteValue1, final int byteValue2) {
        ensureCapacity(2);
        data[length++] = byteValue1;
        data[length++] = byteValue2;
        return this;
    }

    private void ensureCapacity(int minCapacity) {
        if (data.length - length < minCapacity) {
            int newCapacity = data.length * 2;
            if (minCapacity > newCapacity) {
                newCapacity = minCapacity;
            }
            int[] newData = new int[newCapacity];
            System.arraycopy(data, 0, newData, 0, length);
            data = newData;
        }
    }
}

public final ByteVector put11(final int byteValue1, final int byteValue2) {
    if (data == null || data.length < byteValue1 + byteValue2) {
        resize(byteValue1 + byteValue2);
    }
    data[byteValue1] = (byte) byteValue1;
    data[byteValue2] = (byte) byteValue2;
    return this;
}

public ByteVector put11(final int byteValue1, final int byteValue2) {
    if (ByteVector.this.size + 2 > ByteVector.this.vector.length) {
        ByteVector.this.enlargeSize(2);
    }
    ByteVector.this.data[ByteVector.this.size++] = (byte) byteValue1;
    ByteVector.this.data[ByteVector.this.size++] = (byte) byteValue2;
    return this;
}

boolean put11(final int byteValue1, final int byteValue2) {
    if (byteValue1 < 0 || byteValue1 > 255 || byteValue2 < 0 || byteValue2 > 255) {
        throw new IllegalArgumentException("byte value must be between 0 and 255");
    }

    int newLength = length + 2;
    if (data.length < newLength) {
        resize(newLength);
    }

    data[length++] = (byte) byteValue1;
    data[length++] = (byte) byteValue2;

    return this;
}

public final ByteVector put11(final int byteValue1, final int byteValue2) {
    byte[] data = new byte[2];
    data[0] = (byte) byteValue1;
    data[1] = (byte) byteValue2;
    return put11(data);
}

