public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || file.isDirectory()) {
        throw new IOException("Invalid file");
    }
    List<ThreadSnapshot> threadSnapshots = new ArrayList<ThreadSnapshot>();
    try (BufferedInputStream inputStream = new BufferedInputStream(new FileInputStream(file))) {
        int read;
        while ((read = inputStream.read()) != -1) {
            if (read == 0) {
                continue;
            }
            ThreadSnapshot threadSnapshot = new ThreadSnapshot();
            threadSnapshot.setThreadId(readUnsignedInteger(inputStream));
            threadSnapshot.setThreadName(readUTF8String(inputStream));
            threadSnapshot.setThreadState(readUTF8String(inputStream));
            threadSnapshot.setStackTrace(readStackTrace(inputStream));
            threadSnapshot.setTimeRange(timeRanges);
            threadSnapshots.add(threadSnapshot);
        }
    }
    return threadSnapshots;
}

private static int readUnsignedInteger(InputStream inputStream) throws IOException {
    int b1 = inputStream.read();
    int b2 = inputStream.read();
    int b3 = inputStream.read();
    int b4 = inputStream.read();
    return (b1 << 24) | (b2 << 16) | (b3 << 8) | (b4 << 0);
}

private static String readUTF8String(InputStream inputStream) throws IOException {
    int stringLength = readUnsignedInteger(inputStream);
    byte[] bytes = new byte[stringLength];
    int read = inputStream.read(bytes, 0, stringLength);
    if (read != stringLength) {
        throw new IOException("Failed to read string");
    }
    return new String(bytes, "UTF-8");
}
